insert into "psychological_state_signals" ("signal_id", "state_code", "state_name", "signal_type", "observable_indicator", "example_phrases", "score_per_instance", "trigger_threshold", "protocol_adjustment", "source_document", "is_active", "created_at") values ('1', 'A', 'Stress / Hyperactivation', 'Speed / urgency language', 'Phrases indicating rush, pressure, no time', '''We need to move fast,'' ''There is no time,'' ''Just tell me what to do''', '2', '6 points in one response', 'Slow the pace. Acknowledge time pressure before continuing. Use one question only.', 'Psychological State Scoring Table — Acute State Detection', 'true', '2026-07-26 05:12:17.653652+00') on conflict do nothing;
insert into "psychological_state_signals" ("signal_id", "state_code", "state_name", "signal_type", "observable_indicator", "example_phrases", "score_per_instance", "trigger_threshold", "protocol_adjustment", "source_document", "is_active", "created_at") values ('2', 'A', 'Stress / Hyperactivation', 'Absolutist language', 'Always / never / impossible / definitely in uncertain contexts', '''This will definitely work,'' ''That is impossible,'' ''We can never recover''', '2', '4 points across 3 responses', 'Gently test the absolute. ''When you say never — has there been a time where something similar has worked?''', 'Psychological State Scoring Table — Acute State Detection', 'true', '2026-07-26 05:12:17.653652+00') on conflict do nothing;
insert into "psychological_state_signals" ("signal_id", "state_code", "state_name", "signal_type", "observable_indicator", "example_phrases", "score_per_instance", "trigger_threshold", "protocol_adjustment", "source_document", "is_active", "created_at") values ('3', 'A', 'Stress / Hyperactivation', 'Topic jumping / fragmentation', 'Answers jump between unrelated topics without resolution', 'Starts answering Q about sales, pivots to team conflict, pivots to funding unprompted', '3', '3 points in one response', 'Anchor the founder back. ''Let us stay with the sales question for a moment — you mentioned...''', 'Psychological State Scoring Table — Acute State Detection', 'true', '2026-07-26 05:12:17.653652+00') on conflict do nothing;
insert into "psychological_state_signals" ("signal_id", "state_code", "state_name", "signal_type", "observable_indicator", "example_phrases", "score_per_instance", "trigger_threshold", "protocol_adjustment", "source_document", "is_active", "created_at") values ('4', 'A', 'Stress / Hyperactivation', 'Excessive detail with no conclusion', 'Over-explains context without reaching a point', '3+ paragraphs of background before stating the actual problem', '2', '6 points in session', 'Summarise what has been said and ask a direct closed question to anchor.', 'Psychological State Scoring Table — Acute State Detection', 'true', '2026-07-26 05:12:17.653652+00') on conflict do nothing;
insert into "psychological_state_signals" ("signal_id", "state_code", "state_name", "signal_type", "observable_indicator", "example_phrases", "score_per_instance", "trigger_threshold", "protocol_adjustment", "source_document", "is_active", "created_at") values ('5', 'A', 'Stress / Hyperactivation', 'Rapid escalation language', 'Sudden shift to extreme language about stakes', '''If this fails my family loses everything,'' ''I am out of options''', '4', '4 points (single instance)', 'Pause. Acknowledge. ''That sounds like a really heavy weight to carry. Before we go further — how are you doing?''', 'Psychological State Scoring Table — Acute State Detection', 'true', '2026-07-26 05:12:17.653652+00') on conflict do nothing;
insert into "psychological_state_signals" ("signal_id", "state_code", "state_name", "signal_type", "observable_indicator", "example_phrases", "score_per_instance", "trigger_threshold", "protocol_adjustment", "source_document", "is_active", "created_at") values ('6', 'B', 'Withdrawal / Shutdown', 'Minimal responses', 'One word or one sentence answers to open questions', '''Fine.'' / ''Not sure.'' / ''It is okay.''', '2', '6 points across 3 responses', 'Normalise. ''It is completely okay to say you are not sure. What does it actually feel like right now?''', 'Psychological State Scoring Table — Acute State Detection', 'true', '2026-07-26 05:12:17.653652+00') on conflict do nothing;
insert into "psychological_state_signals" ("signal_id", "state_code", "state_name", "signal_type", "observable_indicator", "example_phrases", "score_per_instance", "trigger_threshold", "protocol_adjustment", "source_document", "is_active", "created_at") values ('7', 'B', 'Withdrawal / Shutdown', 'Deflection hedging', 'Avoids direct answers with vague qualifiers', '''Maybe,'' ''Perhaps,'' ''I think possibly,'' ''It could be''', '1', '5 points in one response', 'Ask for specificity gently. ''If you had to choose one — which feels most true?''', 'Psychological State Scoring Table — Acute State Detection', 'true', '2026-07-26 05:12:17.653652+00') on conflict do nothing;
insert into "psychological_state_signals" ("signal_id", "state_code", "state_name", "signal_type", "observable_indicator", "example_phrases", "score_per_instance", "trigger_threshold", "protocol_adjustment", "source_document", "is_active", "created_at") values ('8', 'B', 'Withdrawal / Shutdown', 'Flat affirmatives', 'Agrees with everything without engagement', '''Yes,'' ''Exactly,'' ''Right,'' repeated without elaboration', '2', '6 points across 3 responses', 'Break the pattern. ''Tell me something that is not going well — what is the hardest thing right now?''', 'Psychological State Scoring Table — Acute State Detection', 'true', '2026-07-26 05:12:17.653652+00') on conflict do nothing;
insert into "psychological_state_signals" ("signal_id", "state_code", "state_name", "signal_type", "observable_indicator", "example_phrases", "score_per_instance", "trigger_threshold", "protocol_adjustment", "source_document", "is_active", "created_at") values ('9', 'B', 'Withdrawal / Shutdown', 'Passive voice / third-person deflection', 'Removes self from events', '''Mistakes were made,'' ''Things did not go as planned,'' ''The team decided''', '3', '3 points in one response', 'Bring the founder back in. ''When you say the team decided — what was your role in that?''', 'Psychological State Scoring Table — Acute State Detection', 'true', '2026-07-26 05:12:17.653652+00') on conflict do nothing;
insert into "psychological_state_signals" ("signal_id", "state_code", "state_name", "signal_type", "observable_indicator", "example_phrases", "score_per_instance", "trigger_threshold", "protocol_adjustment", "source_document", "is_active", "created_at") values ('10', 'B', 'Withdrawal / Shutdown', 'Repeated reassurance phrases', 'Identical reassuring phrases across multiple answers', '''It is fine,'' ''We will figure it out,'' ''Not a big deal'' repeated 3+ times', '2', '6 points across session', 'Name it without confronting it. ''You have said it is fine a few times — I want to make sure I am not missing something important.''', 'Psychological State Scoring Table — Acute State Detection', 'true', '2026-07-26 05:12:17.653652+00') on conflict do nothing;
insert into "psychological_state_signals" ("signal_id", "state_code", "state_name", "signal_type", "observable_indicator", "example_phrases", "score_per_instance", "trigger_threshold", "protocol_adjustment", "source_document", "is_active", "created_at") values ('11', 'C', 'Defensiveness / Performance Mode', 'Positive superlative overuse', 'Excessive optimism and enthusiasm about uncertain outcomes', '''This is incredible,'' ''We are absolutely going to crush it,'' ''Revolutionary product''', '2', '8 points in session', 'Test the optimism gently. ''That sounds exciting. What is the one thing that could go wrong that worries you most?''', 'Psychological State Scoring Table — Acute State Detection', 'true', '2026-07-26 05:12:17.653652+00') on conflict do nothing;
insert into "psychological_state_signals" ("signal_id", "state_code", "state_name", "signal_type", "observable_indicator", "example_phrases", "score_per_instance", "trigger_threshold", "protocol_adjustment", "source_document", "is_active", "created_at") values ('12', 'C', 'Defensiveness / Performance Mode', 'Reframing failures as lessons unprompted', 'Proactively spins setbacks before being asked', '''We actually learned so much from that failure,'' ''It was a blessing in disguise''', '3', '3 points in one response', 'Acknowledge the reframe, then go deeper. ''That is a healthy perspective. What did it actually feel like in the moment it happened?''', 'Psychological State Scoring Table — Acute State Detection', 'true', '2026-07-26 05:12:17.653652+00') on conflict do nothing;
insert into "psychological_state_signals" ("signal_id", "state_code", "state_name", "signal_type", "observable_indicator", "example_phrases", "score_per_instance", "trigger_threshold", "protocol_adjustment", "source_document", "is_active", "created_at") values ('13', 'C', 'Defensiveness / Performance Mode', 'Credential leading', 'Leads with credentials, logos, or social proof before answering diagnostic questions', '''We won X award,'' ''We were covered in Forbes,'' ''Our investors include...''', '2', '6 points in session', 'Validate, then redirect. ''That is great context. Tell me more about what the business looks like day to day.''', 'Psychological State Scoring Table — Acute State Detection', 'true', '2026-07-26 05:12:17.653652+00') on conflict do nothing;
insert into "psychological_state_signals" ("signal_id", "state_code", "state_name", "signal_type", "observable_indicator", "example_phrases", "score_per_instance", "trigger_threshold", "protocol_adjustment", "source_document", "is_active", "created_at") values ('14', 'C', 'Defensiveness / Performance Mode', 'Answering different question', 'Consistently answers the question they wish they were asked, not the one asked', 'Question about sales pipeline → answer about product vision', '3', '3 points across 3 responses', 'Name it kindly. ''I want to make sure I understood — specifically about the pipeline, how many active conversations do you have right now?''', 'Psychological State Scoring Table — Acute State Detection', 'true', '2026-07-26 05:12:17.653652+00') on conflict do nothing;
insert into "psychological_state_signals" ("signal_id", "state_code", "state_name", "signal_type", "observable_indicator", "example_phrases", "score_per_instance", "trigger_threshold", "protocol_adjustment", "source_document", "is_active", "created_at") values ('15', 'C', 'Defensiveness / Performance Mode', 'Advisor dropping', 'Mentions high-profile advisors or networks to establish credibility under pressure', '''Our advisor who was ex-Google said...'' / ''Sequoia told us...''', '2', '6 points in session', 'Accept it without dwelling. Return to the diagnostic question without further attention to the credential.', 'Psychological State Scoring Table — Acute State Detection', 'true', '2026-07-26 05:12:17.653652+00') on conflict do nothing;
insert into "psychological_state_signals" ("signal_id", "state_code", "state_name", "signal_type", "observable_indicator", "example_phrases", "score_per_instance", "trigger_threshold", "protocol_adjustment", "source_document", "is_active", "created_at") values ('16', 'D', 'Emotional Distress / Crisis Signals', 'Identity collapse language', 'Conflates personal failure with business failure', '''I am a failure,'' ''I cannot do this,'' ''I was not meant for this''', '5', '5 points (single instance)', 'STOP the diagnostic. Shift fully to empathetic listening. ''That sounds incredibly hard. Can you tell me more about how you are feeling?''', 'Psychological State Scoring Table — Acute State Detection', 'true', '2026-07-26 05:12:17.653652+00') on conflict do nothing;
insert into "psychological_state_signals" ("signal_id", "state_code", "state_name", "signal_type", "observable_indicator", "example_phrases", "score_per_instance", "trigger_threshold", "protocol_adjustment", "source_document", "is_active", "created_at") values ('17', 'D', 'Emotional Distress / Crisis Signals', 'Helplessness / hopelessness language', 'Expresses no belief that anything can improve', '''Nothing will work,'' ''I have tried everything,'' ''It is pointless''', '5', '5 points (single instance)', 'STOP the diagnostic. Acknowledge. ''I hear you. This sounds really overwhelming. You do not have to have all the answers right now.''', 'Psychological State Scoring Table — Acute State Detection', 'true', '2026-07-26 05:12:17.653652+00') on conflict do nothing;
insert into "psychological_state_signals" ("signal_id", "state_code", "state_name", "signal_type", "observable_indicator", "example_phrases", "score_per_instance", "trigger_threshold", "protocol_adjustment", "source_document", "is_active", "created_at") values ('18', 'D', 'Emotional Distress / Crisis Signals', 'Isolation language', 'Expresses being completely alone with the problem', '''No one understands,'' ''I cannot tell anyone,'' ''I am completely alone in this''', '4', '4 points (single instance)', 'Normalise and gently connect. ''Many founders feel this way and it is one of the hardest parts. Do you have anyone you trust outside the business?''', 'Psychological State Scoring Table — Acute State Detection', 'true', '2026-07-26 05:12:17.653652+00') on conflict do nothing;
insert into "psychological_state_signals" ("signal_id", "state_code", "state_name", "signal_type", "observable_indicator", "example_phrases", "score_per_instance", "trigger_threshold", "protocol_adjustment", "source_document", "is_active", "created_at") values ('19', 'D', 'Emotional Distress / Crisis Signals', 'Mentions of sleep deprivation or health neglect', 'Reveals extended period of physical neglect', '''I have not slept properly in weeks,'' ''I cannot remember the last time I ate a proper meal''', '3', '3 points (single instance)', 'Acknowledge physical state before continuing. ''Before we go further — how long has it been like this? Your capacity to think clearly matters here.''', 'Psychological State Scoring Table — Acute State Detection', 'true', '2026-07-26 05:12:17.653652+00') on conflict do nothing;
insert into "psychological_state_signals" ("signal_id", "state_code", "state_name", "signal_type", "observable_indicator", "example_phrases", "score_per_instance", "trigger_threshold", "protocol_adjustment", "source_document", "is_active", "created_at") values ('20', 'D', 'Emotional Distress / Crisis Signals', 'Catastrophic certainty', 'States extremely negative outcomes as definite facts', '''We are going to fail,'' ''This is over,'' ''There is no way out''', '5', '5 points (single instance)', 'STOP the diagnostic. Acknowledge without agreeing or disagreeing. Do not offer solutions. Ask one question: ''What would need to be true for things to feel even slightly more manageable?''', 'Psychological State Scoring Table — Acute State Detection', 'true', '2026-07-26 05:12:17.653652+00') on conflict do nothing;
